import { Buffer } from 'buffer';

import {
  hexConcat,
  hexZeroPad,
  keccak256,
  toUtf8Bytes,
} from '../ethersV6Compat.ts';

import type { PaliAuthenticatorModuleId } from './contracts.ts';

export const PALI_CREATE2_DEPLOYER_ADDRESS =
  '0x4e59b44847b379578588920cA78FbF26c0B4956C';

export const PALI_CANONICAL_ENTRYPOINT_ADDRESS =
  '0x433709009B8330FDa32311DF1C2AFA402eD8D009';

export const PALI_CREATE2_DEPLOYER_MIN_RUNTIME_BYTE_LENGTH = 1;
export const PALI_INFRASTRUCTURE_VERSION = 'PALI_SMART_ACCOUNT_ERC7579_V2';

// Canonical Multicall3 (https://github.com/mds1/multicall3), present on most
// public EVM chains. On chains where it is absent, Pali deploys the same
// creation bytecode through its CREATE2 infrastructure pipeline at a
// deterministic (non-canonical) address.
export const PALI_MULTICALL3_CANONICAL_ADDRESS =
  '0xcA11bde05977b3631167028862bE2a173976CA11';

// Compact source representation; decoded deployment bytes remain canonical.
const decodeBytecode = (encoded: string): string =>
  `0x${Buffer.from(encoded, 'base64').toString('hex')}`;

// Pali contracts are generated from zksync-os-server contracts/src/pali with official EVM solc 0.8.28, Cancun, via-IR, optimizer enabled, runs=200, and bytecode metadata disabled.
const bytecodes = {
  ecdsaValidator: decodeBytecode(
    ''
  ),
  p256WebAuthnValidator: decodeBytecode(
    ''
  ),
  slhDsaVerifier: decodeBytecode(
    ''
  ),
  slhDsaValidator: decodeBytecode(
    ''
  ),
  compositeValidator: decodeBytecode(
    ''
  ),
  guardianRecoveryModule: decodeBytecode(
    ''
  ),
} as const;

// Official Multicall3 creation bytecode, extracted from the pre-signed
// deployment transaction published in https://github.com/mds1/multicall3
// (deployer 0x05f32B3cC3888453ff71B01135B34FF8e41263F2, nonce 0, which yields
// the canonical 0xcA11bde05977b3631167028862bE2a173976CA11 address on chains
// where that transaction was replayed). Multicall3 has no constructor
// arguments, so deploying the same creation code via CREATE2 produces an
// identical contract at a Pali-deterministic address.
const multicall3Bytecode = decodeBytecode(
  ''
);

export type PaliInfrastructureContractId =
  | keyof typeof bytecodes
  | keyof typeof standardBytecodes
  | 'multicall3';

export type PaliInfrastructureContract = {
  address: string;
  bytecodeHash?: string;
  deployCalldata?: string;
  displayName: string;
  // Required infrastructure that must be deployed by the chain launch flow, not
  // by the wallet's user-triggered CREATE2 deployment helper.
  externallyDeployed?: boolean;
  id: PaliInfrastructureContractId;
  moduleId?: PaliAuthenticatorModuleId;
  // Optional contracts are deployed by the infrastructure flow when missing
  // but do not gate smart-account readiness (they are pure optimizations).
  optional?: boolean;
  runtimeCodeHash?: string;
  salt: string;
};

// EntryPoint v0.9 is the official account-abstraction v0.9.0 artifact (solc 0.8.28, via-IR, runs=1_000_000).
// accountImplementation and factory embed the canonical EntryPoint v0.9 address as a constructor argument.
const standardBytecodes = {
  entryPoint: decodeBytecode(
    ''
  ),
  accountImplementation: decodeBytecode(
    ''
  ),
  factory: decodeBytecode(
    ''
  ),
} as const;

const salt = (name: string) =>
  keccak256(toUtf8Bytes(`${PALI_INFRASTRUCTURE_VERSION}:${name}`));

const deployCalldata = (contractSalt: string, initCode: string) =>
  hexConcat([contractSalt, initCode]);

const create2Address = (contractSalt: string, initCode: string) =>
  `0x${keccak256(
    hexConcat([
      '0xff',
      PALI_CREATE2_DEPLOYER_ADDRESS,
      contractSalt,
      keccak256(initCode),
    ])
  ).slice(-40)}`;

const entryPointSalt =
  '0x7702864008ddeab30aa67b7adc3d2653bc8d162714b1fe8fe4582df814f3bf61';
const accountImplementationSalt = salt('account-implementation');
const ecdsaValidatorSalt = salt('ecdsa-validator');
const p256WebAuthnValidatorSalt = salt('p256-webauthn-validator');
const slhDsaVerifierSalt = salt('slh-dsa-verifier');
const slhDsaValidatorSalt = salt('slh-dsa-validator');
const compositeValidatorSalt = salt('composite-validator');
const guardianRecoveryModuleSalt = salt('guardian-recovery-module');
const factorySalt = salt('factory');
const multicall3Salt = salt('multicall3');

const slhDsaVerifierAddress = create2Address(
  slhDsaVerifierSalt,
  bytecodes.slhDsaVerifier
);
const slhDsaVerifierCodeHash =
  '0x31e33d9848db6a8821cf39adeb347aff047a308f52b04aee2a398e29fee8b628';
const slhDsaValidatorInitCode = hexConcat([
  bytecodes.slhDsaValidator,
  hexZeroPad(slhDsaVerifierAddress, 32),
  slhDsaVerifierCodeHash,
]);

export const PALI_INFRASTRUCTURE_CONTRACTS: PaliInfrastructureContract[] = [
  {
    address: PALI_CANONICAL_ENTRYPOINT_ADDRESS,
    bytecodeHash: keccak256(standardBytecodes.entryPoint),
    deployCalldata: deployCalldata(
      entryPointSalt,
      standardBytecodes.entryPoint
    ),
    displayName: 'ERC-4337 EntryPoint v0.9',
    id: 'entryPoint',
    salt: entryPointSalt,
  },
  {
    address: create2Address(
      accountImplementationSalt,
      standardBytecodes.accountImplementation
    ),
    bytecodeHash: keccak256(standardBytecodes.accountImplementation),
    deployCalldata: deployCalldata(
      accountImplementationSalt,
      standardBytecodes.accountImplementation
    ),
    displayName: 'Pali smart account implementation',
    id: 'accountImplementation',
    salt: accountImplementationSalt,
  },
  {
    address: create2Address(ecdsaValidatorSalt, bytecodes.ecdsaValidator),
    bytecodeHash: keccak256(bytecodes.ecdsaValidator),
    deployCalldata: deployCalldata(
      ecdsaValidatorSalt,
      bytecodes.ecdsaValidator
    ),
    displayName: 'ECDSA validator module',
    id: 'ecdsaValidator',
    moduleId: 'ecdsa',
    salt: ecdsaValidatorSalt,
  },
  {
    address: create2Address(
      p256WebAuthnValidatorSalt,
      bytecodes.p256WebAuthnValidator
    ),
    bytecodeHash: keccak256(bytecodes.p256WebAuthnValidator),
    deployCalldata: deployCalldata(
      p256WebAuthnValidatorSalt,
      bytecodes.p256WebAuthnValidator
    ),
    displayName: 'P-256 passkey validator module',
    id: 'p256WebAuthnValidator',
    moduleId: 'p256-webauthn',
    salt: p256WebAuthnValidatorSalt,
  },

  {
    address: slhDsaVerifierAddress,
    bytecodeHash: keccak256(bytecodes.slhDsaVerifier),
    deployCalldata: deployCalldata(
      slhDsaVerifierSalt,
      bytecodes.slhDsaVerifier
    ),
    displayName: 'Pali SLH-DSA verifier',
    id: 'slhDsaVerifier',
    salt: slhDsaVerifierSalt,
  },
  {
    address: create2Address(slhDsaValidatorSalt, slhDsaValidatorInitCode),
    bytecodeHash: keccak256(slhDsaValidatorInitCode),
    deployCalldata: deployCalldata(
      slhDsaValidatorSalt,
      slhDsaValidatorInitCode
    ),
    displayName: 'Pali SLH-DSA validator',
    id: 'slhDsaValidator',
    moduleId: 'slh-dsa',
    salt: slhDsaValidatorSalt,
  },
  {
    address: create2Address(
      compositeValidatorSalt,
      bytecodes.compositeValidator
    ),
    bytecodeHash: keccak256(bytecodes.compositeValidator),
    deployCalldata: deployCalldata(
      compositeValidatorSalt,
      bytecodes.compositeValidator
    ),
    displayName: 'Composite validator module',
    id: 'compositeValidator',
    moduleId: 'composite',
    salt: compositeValidatorSalt,
  },
  {
    address: create2Address(
      guardianRecoveryModuleSalt,
      bytecodes.guardianRecoveryModule
    ),
    bytecodeHash: keccak256(bytecodes.guardianRecoveryModule),
    deployCalldata: deployCalldata(
      guardianRecoveryModuleSalt,
      bytecodes.guardianRecoveryModule
    ),
    displayName: 'Guardian recovery module',
    id: 'guardianRecoveryModule',
    moduleId: 'guardian-recovery',
    // Exact solc 0.8.28/Cancun runtime, via-IR, optimizer 200, metadata disabled.
    // Unlike bytecodeHash (creation code), this attests the deployed code before
    // reading its active-operation slot 3 and packed schedule mapping at slot 4.
    runtimeCodeHash:
      '0x542ee89b55395aad286ed856bfad874594ed7ae5b5066d93a52cb2e178e9d446',
    salt: guardianRecoveryModuleSalt,
  },
  {
    // Lean OZ ERC-7579 factory bytecode with the (implementation, entryPoint)
    // constructor args appended. createAccount is gated on
    // entryPoint.senderCreator(), so accounts can only be deployed through the
    // ERC-4337 initCode path.
    address: create2Address(factorySalt, standardBytecodes.factory),
    bytecodeHash: keccak256(standardBytecodes.factory),
    deployCalldata: deployCalldata(factorySalt, standardBytecodes.factory),
    displayName: 'Pali ERC-7579 smart account factory',
    id: 'factory',
    salt: factorySalt,
  },
  {
    address: create2Address(multicall3Salt, multicall3Bytecode),
    bytecodeHash: keccak256(multicall3Bytecode),
    deployCalldata: deployCalldata(multicall3Salt, multicall3Bytecode),
    displayName: 'Multicall3 read aggregator',
    id: 'multicall3',
    optional: true,
    salt: multicall3Salt,
  },
];

export const PALI_INFRASTRUCTURE_BY_ID = Object.fromEntries(
  PALI_INFRASTRUCTURE_CONTRACTS.map((contract) => [contract.id, contract])
) as Record<PaliInfrastructureContractId, PaliInfrastructureContract>;

// All Pali chains share the same canonical infrastructure (the chainId
// parameter is kept for call-site compatibility and future per-chain infra).
export const getPaliInfrastructureContracts = (
  // eslint-disable-next-line no-unused-vars, @typescript-eslint/no-unused-vars
  chainId?: number
): PaliInfrastructureContract[] => PALI_INFRASTRUCTURE_CONTRACTS;

export const getPaliInfrastructureById = (
  // eslint-disable-next-line no-unused-vars, @typescript-eslint/no-unused-vars
  chainId?: number
): Record<PaliInfrastructureContractId, PaliInfrastructureContract> =>
  PALI_INFRASTRUCTURE_BY_ID;

export const getPaliCanonicalEntryPointAddress = (chainId?: number): string =>
  getPaliInfrastructureById(chainId).entryPoint.address;

export const getPaliCanonicalFactoryAddress = (chainId?: number): string =>
  getPaliInfrastructureById(chainId).factory.address;

// The zkSYS tank is immutable in the canonical OS guest on both networks.
// Keep this protocol binding separate from user-editable RPC metadata; the
// launch bootstrap attests the runtime before recording its deployed address.
export const ZKSYS_GAS_TANK_ADDRESSES: Partial<Record<number, string>> = {
  57057: '0xb49943ea232624dd4aa63e18186076c6c99a68ef',
  5757: '0xb49943ea232624dd4aa63e18186076c6c99a68ef',
};

export const getZkSysGasTankAddress = (chainId?: number): string | undefined =>
  chainId === undefined ? undefined : ZKSYS_GAS_TANK_ADDRESSES[chainId];

export const PALI_MODULE_CANONICAL_ADDRESSES: Partial<
  Record<PaliAuthenticatorModuleId, string>
> = {
  composite: PALI_INFRASTRUCTURE_BY_ID.compositeValidator.address,
  ecdsa: PALI_INFRASTRUCTURE_BY_ID.ecdsaValidator.address,
  'guardian-recovery': PALI_INFRASTRUCTURE_BY_ID.guardianRecoveryModule.address,
  'p256-webauthn': PALI_INFRASTRUCTURE_BY_ID.p256WebAuthnValidator.address,
  'slh-dsa': PALI_INFRASTRUCTURE_BY_ID.slhDsaValidator.address,
};

export const PALI_CANONICAL_FACTORY_ADDRESS =
  PALI_INFRASTRUCTURE_BY_ID.factory.address;
